namespace pitTeam.Compat { internal enum NativeNullableReturnOutcome { NativeException, None, BoxedValue, UnsupportedClass } internal static class NativeNullableReturnPolicy { internal static NativeNullableReturnOutcome Classify(long resultPointer, long exceptionPointer, long actualClassPointer, long expectedClassPointer) { if (exceptionPointer != 0) return NativeNullableReturnOutcome.NativeException; if (resultPointer == 0) return NativeNullableReturnOutcome.None; if (actualClassPointer == 0 || expectedClassPointer == 0 || actualClassPointer != expectedClassPointer) return NativeNullableReturnOutcome.UnsupportedClass; return NativeNullableReturnOutcome.BoxedValue; } } }
